"""Render the source audit without interpreting source detection as diagnosis."""
import os,json
from pathlib import Path
os.environ.setdefault('MPLCONFIGDIR','/tmp/medical-ai-mpl')
import numpy as np
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
from reportlab.platypus import SimpleDocTemplate,Paragraph,Spacer,Image,Table,TableStyle
from reportlab.lib.styles import getSampleStyleSheet,ParagraphStyle
from reportlab.pdfbase import pdfmetrics
from reportlab.pdfbase.ttfonts import TTFont
from reportlab.lib import colors
ROOT=Path(__file__).resolve().parents[1]

def main():
    out=ROOT/'reports/original_512/source_audit';s=json.loads((out/'summary.json').read_text());p=np.load(out/'features_and_oof.npz');x=p['features'];normal=p['clinical_labels']==0;source=p['source'];names={'dimensions':'Dimensions','appearance':'Appearance','combined':'Combined'}
    fig,axes=plt.subplots(1,3,figsize=(13,4));j=0;labels=[]
    for label in [0,1]:
        for name in names:
            v=s['results'][f'{label}__{name}'];axes[0].errorbar(v['auroc'],j,xerr=[[v['auroc']-v['ci'][0]],[v['ci'][1]-v['auroc']]],fmt='o',color=['#167699','#c35a29'][label],capsize=3);labels.append(('NORMAL' if label==0 else 'PNEUMONIA')+' / '+names[name]);j+=1
    axes[0].set(yticks=range(6),yticklabels=labels,xlabel='Source-prediction AUROC',xlim=(.45,1));axes[0].tick_params(axis='y',labelsize=8);axes[0].axvline(.5,color='gray',ls='--');axes[0].invert_yaxis()
    for axis,column,title in [(axes[1],0,'Original width'),(axes[2],1,'Original height')]:
        values=np.exp(x[normal,column]);bins=np.linspace(values.min(),values.max(),25)
        for src,label,color in [(0,'Development','#167699'),(1,'Test','#c35a29')]:axis.hist(np.exp(x[normal&(source==src),column]),bins=bins,density=True,histtype='step',label=label,color=color,lw=2)
        axis.set(xlabel=title+' (pixels)',ylabel='Density, NORMAL only');axis.legend(fontsize=8)
    fig.tight_layout();fig.savefig(out/'source_shift.png',dpi=180);fig.savefig(out/'source_shift.pdf');plt.close(fig)
    lines=['# Herkunftsaudit: Warum versagt die Übertragung bei Normalbildern?','','Explorative Nachanalyse vom 11. November 2026. Ausgangspunkt ist die dokumentierte Spezifitätslücke des unveränderten 512px-Modells. Die Analyse prüft Unterschiede zwischen Teilbeständen; sie trainiert keine neue medizinische Diagnose und erklärt Fehler nicht kausal.','','## Ergebnis','','| Klinische Bildklasse | Merkmale | Herkunfts-AUROC [95 %] |','|---|---|---:|']
    for label in [0,1]:
        for name in names:
            v=s['results'][f'{label}__{name}'];lines.append(f"| {['NORMAL','PNEUMONIA'][label]} | {name} | {v['auroc']:.3f} [{v['ci'][0]:.3f}; {v['ci'][1]:.3f}] |")
    lines+=['','**Das sind AUROCs für die Herkunft eines Bildes, nicht für Pneumonie.** Positive Herkunft bedeutet offizieller Test, negative Herkunft bedeutet ursprünglicher Trainingsbestand einschließlich Modellwahl/Kalibrierung. Die klinische Klasse wird konstant gehalten; unterschiedliche Pneumonie-Anteile können den Unterschied daher nicht allein erklären.','','![Herkunfts-Trennbarkeit und Größenverteilungen](source_shift.png)','','Normalbilder zeigen eine deutlich stärkere Trennbarkeit der Teilbestände als Pneumoniebilder. Das ist mit der ungleichen Übertragung von Sensitivität und Spezifität vereinbar. Es beweist weder eine bestimmte Ursache noch, dass der Bildklassifikator diese Merkmale als Abkürzung verwendet. Insbesondere wird die Originalgröße dem medizinischen Modell nicht als Zahlenwert gegeben; Bildgeometrie, Abtastung und Bildinhalt können damit zusammenhängen.','','## Durchführung','','- Unverändert 5.371 bereinigte Bilder; 1.579 NORMAL und 3.792 PNEUMONIA. Keine neuen Bilder und keine neue Aufteilung des medizinischen Tests.','- Drei festgelegte Merkmalsgruppen: logarithmierte Originalbreite/-höhe; sieben Erscheinungsmerkmale; deren Kombination. Keine IDs, Dateinamen oder medizinischen Modellvorhersagen als Eingaben der Herkunftsklassifikatoren.','- Erscheinungsmerkmale: Mittelwert, Standardabweichung, 5./95. Perzentil, Mittelwerte am äußeren 10%-Rand und im zentralen 50%-Rechteck sowie mittlere benachbarte Grauwertdifferenzen. Schwarzes Padding wird anhand der bekannten Geometrie entfernt; echte schwarze Bildpixel bleiben erhalten.','- Je klinischer Klasse fünf gruppierte Folds. Standardisierung ausschließlich im Trainingsfold. Logistische Regression mit festem C=1 und ausgeglichenen Herkunftsklassengewichten. Jede gespeicherte Vorhersage stammt von einem Modell, das diese Dateinamen-Gruppe nicht zum Fit verwendet hat.','- 2.000 nach Herkunft stratifizierte Gruppen-Bootstraps der festen Out-of-fold-Vorhersagen. Keine erneute Modellanpassung im Bootstrap: Intervalle enthalten keine vollständige CV-/Trainingsunsicherheit. Überlappende Trainingsfolds und unvollständig bekannte Identitäten begrenzen die Schlussfolgerungen.','','Die Herkunftsmodelle verwenden absichtlich Bilder aus beiden Ursprüngen zur gruppierten Kreuzvalidierung. Das ist eine Diagnose des Datensatzes, kein unabhängiger externer Test des medizinischen Modells. Der bekannte Testbestand wird dadurch nicht wieder unberührt.','','## Zusammenhang mit falsch positiven Normalbildern','','Alle vorab benannten Merkmale werden berichtet; keine Auswahl nur günstiger Zusammenhänge. Spearman-Korrelation mit dem festen medizinischen Logit innerhalb der 231 Test-Normalbilder, rein deskriptiv. Mediane bei Log-Breite/-Höhe liegen auf der logarithmischen Skala; die übrigen Größen beziehen sich auf Graustufen 0–1.','','| Merkmal | Spearman mit Pneumonie-Logit | Median falsch positiv | Median richtig negativ |','|---|---:|---:|---:|']
    for name,v in s['test_normal_associations'].items():lines.append(f"| {name} | {v['spearman_logit']:+.3f} | {v['false_positive_median']:.4f} | {v['true_negative_median']:.4f} |")
    lines+=['','Diese Zusammenhänge können durch andere Bildmerkmale oder Fallmischung erklärt sein. Kein kausaler Nachweis, keine klinische Erklärung und kein Anlass, die Entscheidungsschwelle auf den bekannten Testfällen nachzustellen.','','## Konsequenz für das Projekt','','Die nächste belastbare Verbesserung benötigt eine besser passende, unabhängig erhobene Validierungs-/Kalibrierungskohorte und gezielte, vorab festgelegte Prüfungen der Bildvorverarbeitung. Mehr Epochen oder Parameter allein adressieren die beobachtete Herkunftslücke nicht nachweislich. Die bestehenden Diagnosemodelle, Schwellen, Vorhersagen und das Core-ML-Paket bleiben unverändert.','','## Nachprüfbarkeit','','[Protokoll](../../../configs/original_source_audit.json), vor der Auswertung als `81c94b1` versioniert. [Zusammenfassung](summary.json) · [Merkmale und OOF-Vorhersagen](features_and_oof.npz) · [Fold-Modelle](fold_models.npz) · [Verteilungen](distributions.csv) · [Bootstrap](bootstrap.npz) · [Unabhängiger Prüfer](verification.json).','','```bash','python experiments/original_source_audit.py','python scripts/verify_original_source_audit.py','python scripts/report_original_source_audit.py','```','','Den Experimentlauf in einer frischen Arbeitskopie ausführen; der Ergebnisordner wird nicht überschrieben. Voraussetzung ist die vollständig vorbereitete Originalbild-Studie.']
    (out/'README.md').write_text('\n'.join(lines)+'\n')
    pdfmetrics.registerFont(TTFont('Audit','/usr/share/fonts/truetype/dejavu/DejaVuSans.ttf'));pdfmetrics.registerFont(TTFont('AuditBold','/usr/share/fonts/truetype/dejavu/DejaVuSans-Bold.ttf'));styles=getSampleStyleSheet();styles.add(ParagraphStyle(name='A',fontName='Audit',fontSize=9,leading=13,spaceAfter=10));styles.add(ParagraphStyle(name='AT',fontName='AuditBold',fontSize=17,leading=21,spaceAfter=16));story=[]
    def para(t,title=False):story.append(Paragraph(t,styles['AT' if title else 'A']))
    para('Herkunftslücke bei Original-Thoraxbildern',True);para('11. November 2026 · Explorative Nachanalyse · Medical AI Reliability Lab')
    para('Das nachtrainierte 512px-Modell erreicht 98,4 % Spezifität auf Kalibrierungsbildern, aber nur 54,5 % im Test. Die neue Analyse prüft, ob sich die Teilbestände innerhalb derselben klinischen Klasse anhand einfacher Bildmerkmale unterscheiden.')
    para('Bei NORMAL-Bildern erkennen Breite und Höhe die Herkunft mit AUROC 0,794 [0,760; 0,826]. Mit zusätzlichen Erscheinungsmerkmalen steigt sie auf 0,849 [0,822; 0,875]. Bei PNEUMONIA liegt der kombinierte Wert nur bei 0,583 [0,543; 0,618]. Diese Zahlen messen Herkunft, nicht Krankheitsdiagnose.')
    story.append(Image(str(out/'source_shift.png'),width=495,height=495*4/13));story.append(Spacer(1,12))
    para('Kontrolle gegen triviale Erklärungen: getrennte Auswertung je klinischer Klasse, keine Dateinamen/IDs als Eingaben, fünf Folds mit getrennten Dateinamen-Gruppen und nur im Trainingsfold angepasste Skalierung. Schwarzes Padding wird vor der Helligkeitsanalyse geometrisch entfernt; echte schwarze Bildpixel bleiben erhalten.')
    para('Unsicherheit: 2.000 nach Herkunft stratifizierte Gruppen-Wiederziehungen der festen Out-of-fold-Vorhersagen. Die Intervalle erfassen keine vollständige Trainings-/CV-Unsicherheit. Die Nachanalyse wurde durch bekannte Testergebnisse motiviert und ist keine unabhängige Bestätigung.')
    para('Bedeutung: Die besonders ausgeprägte Herkunftslücke bei Normalbildern passt zur geringen Testspezifität. Sie belegt keine Ursache der Fehler und keinen bestimmten Shortcut. Die medizinischen Modelle erhalten die ursprüngliche Bildgröße nicht direkt als Zahlenwert. Aufnahmebedingungen, Geometrie, Abtastung und Inhalt können zusammenwirken.')
    para('Die bestehenden Modelle und das Core-ML-Paket bleiben unverändert. Für belastbare Verbesserungen stehen eine unabhängig erhobene, repräsentative Kalibrierungs-/Validierungskohorte und gezielte Vorverarbeitungsprüfungen vor weiteren Aussagen über klinische Nutzbarkeit. Vollständige Tabellen, Merkmale, Fold-Modelle und unabhängige Prüfung: reports/original_512/source_audit/.')
    SimpleDocTemplate(str(out/'research_note.pdf'),pagesize=(595.28,841.89),leftMargin=45,rightMargin=45,topMargin=40,bottomMargin=40).build(story)

if __name__=='__main__':main()
